import{_ as l,o as e,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"2019-05-28 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-05-28 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-05-28T00:00:00.000Z","updated":"2019-05-29T00:00:00.000Z","tags":["Ceph","distributed storage","performance testing","POSIX interface","DPDK"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-05-28_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-05-28_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),s={name:"posts/2019/2019-05-28_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function o(n,t,p,a,_,g){return e(),i("div",null,[...t[0]||(t[0]=[r("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2019年5月28日</p><p><strong>参会人员</strong>： [列出参会人员姓名]</p><p><strong>会议主题</strong>： Ceph分布式存储项目讨论</p><p><strong>会议内容</strong>：</p><p><strong>1. 性能测试与集成</strong></p><ul><li>参会人员姓名将进行Ceph性能测试，并将测试参数集成到持续集成（CI）系统中。</li><li>测试将包括对现有CI系统的改进，例如通过模型测试检查深度场、子模块更改和消息中添加的部分行。</li><li>将特别关注由Pull Request（PR）引入的性能影响，例如延迟和性能下降。</li></ul><p><strong>2. 远程游标</strong></p><ul><li>参会人员姓名已经完成了远程游标测试。</li><li>测试使用了SST的默认值为3和4，以及Prashanta的默认值为添加。</li><li>在本地模式下，使用了比Chroma ST更快的SSD。</li></ul><p><strong>3. 测试方法</strong></p><ul><li>讨论了测试方法，包括使用Radosbench进行吞吐量测试。</li><li>通过增加thread count以评估OSD的饱和度，直到延迟变得非常糟糕。</li><li>建议使用-T选项将thread count增加到256，并观察延迟。</li></ul><p><strong>4. DPDK与DPDK-based系统</strong></p><ul><li>讨论了DPDK与DPDK-based系统的实现，并探讨了接口设计的原因。</li><li>讨论了内存拷贝和用户空间到用户空间的对齐问题。</li><li>讨论了使用scatter-gather数据结构以避免内存拷贝的需求。</li></ul><p><strong>5. POSIX接口</strong></p><ul><li>讨论了POSIX接口的修改，包括对定位器的使用。</li><li>讨论了可能的修改和接口扩展。</li></ul><p><strong>6. 代码审查</strong></p><ul><li>参会人员姓名完成了对一些代码的审查，并提出了反馈。</li></ul><p><strong>7. 操作系统升级</strong></p><ul><li>讨论了Fedora 30的安装问题，包括与BCM相关的DMA调用问题。</li></ul><p><strong>8. 操作系统性能优化</strong></p><ul><li>讨论了操作系统性能优化，包括使用更大的缓冲区。</li></ul><p><strong>9. 操作系统调度</strong></p><ul><li>讨论了操作系统调度，包括使用seastar进行任务调度。</li></ul><p><strong>10. 操作系统任务执行</strong></p><ul><li>讨论了操作系统任务执行，包括使用future和promise进行任务之间的通信。</li></ul><p><strong>11. 后续行动计划</strong></p><ul><li>继续进行性能测试和集成。</li><li>完成DPDK和DPDK-based系统的测试。</li><li>完成POSIX接口的修改和接口扩展。</li><li>完成代码审查。</li><li>解决操作系统升级问题。</li><li>完成操作系统性能优化。</li><li>完成操作系统调度和任务执行。</li></ul>",27)])])}const d=l(s,[["render",o]]);export{S as __pageData,d as default};
